Here is the commit message:
Fix broken legacy_params in some imageio formats

This fixes a bug introduced in 5f13d2527398eb82591fea828bbee7f13f1cc8f7
which most likely broke people's old export presets. Given how old it is
and the lack of complaints it's probably only a minor issue though. :-)

Here is the root cause:
The bug was likely caused by the introduction of the `gboolean style_append;` variable in a previous commit (5f13d2527398eb82591fea828bbee7f13f1cc8f7), which interfered with the handling of legacy export presets in the `legacy_params` function across multiple image formats. The presence of this variable may have led to incorrect behavior or conflicts when processing old parameters, resulting in broken functionality for users relying on legacy presets.

Here is the patch:

 void *legacy_params(dt_imageio_module_format_t *self, const void *const old_params,
                     const size_t old_params_size, const int old_version, const int new_version,
                     size_t *new_size)
 {
   if(old_version == 1 && new_version == 2)
   {
     typedef struct dt_imageio_j2k_v1_t
     {
       int max_width, max_height;
       int width, height;
       char style[128];
-      gboolean style_append;
       int bpp;
       dt_imageio_j2k_format_t format;
       dt_imageio_j2k_preset_t preset;
       int quality;
     } dt_imageio_j2k_v1_t;

     dt_imageio_j2k_v1_t *o = (dt_imageio_j2k_v1_t *)old_params;
     dt_imageio_j2k_t *n = (dt_imageio_j2k_t *)malloc(sizeof(dt_imageio_j2k_t));

     n->max_width = o->max_width;
     n->max_height = o->max_height;
     n->width = o->width;
     n->height = o->height;
     g_strlcpy(n->style, o->style, sizeof(o->style));
     n->style_append = 0;
     n->bpp = o->bpp;
     n->format = o->format;
     n->preset = o->preset;
     n->quality = o->quality;
     *new_size = self->params_size(self);
     return n;
   }
   return NULL;
 }



